const isCallback = !!$json.callback_query;

const messageText = $json.message?.text || '';
const chatIdFromMessage = $json.message?.chat?.id;
const fromMessage = $json.message?.from || {};

const callbackData = $json.callback_query?.data || '';
const chatIdFromCallback = $json.callback_query?.message?.chat?.id;
const fromCallback = $json.callback_query?.from || {};

const chatId = chatIdFromCallback || chatIdFromMessage;
const from = isCallback ? fromCallback : fromMessage;

const text = isCallback ? String(callbackData || '') : String(messageText || '');

// Minimal state: embed in the workflow data (staticData). For production, replace with DB.
const staticData = this.getWorkflowStaticData('global');
if (!staticData.projects) staticData.projects = {};

const key = String(chatId || 'unknown');
if (!staticData.projects[key]) {
  staticData.projects[key] = {
    project_json: {
      status: 'new',
      created_at: new Date().toISOString(),
      steps_done: {}
    },
    last_micha_message: null
  };
}

const projectState = staticData.projects[key];
projectState.last_micha_message = text;

// Very small event object
let event = { type: isCallback ? 'telegram_button' : 'telegram_message', text };
if (!isCallback && /^\/start\b/.test(text)) event = { type: 'start' };
if (text.includes('Je bloque') || text.includes('❓')) event = { type: 'blocked', text };
if (text === '✅ Fait') event = { type: 'done' };
if (text === '📎 Coller lien') event = { type: 'need_link' };
if (text === '📨 Copier message') event = { type: 'copy_message' };

return [{
  chat_id: chatId,
  micha: { id: from.id, username: from.username, first_name: from.first_name },
  project_state: projectState.project_json,
  last_micha_message: projectState.last_micha_message,
  event
}];

const raw = $json?.content?.[0]?.text || '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Fallback: produce a safe minimal message
  parsed = {
    next_state_patch: {},
    message: {
      text: "Action: colle le lien du dossier (Drive/WeTransfer) pour ce projet.",
      buttons: ["📎 Coller lien", "❓ Je bloque"]
    },
    next_if_blocked: {
      question: "Tu préfères déposer où ?",
      buttons: ["Drive", "WeTransfer"]
    }
  };
}

const text = parsed.message?.text || 'Action: réponds OK.';
const buttons = parsed.message?.buttons || ["✅ Fait", "❓ Je bloque"];

// Telegram inline keyboard expects array of rows.
const rows = buttons.map(b => [{ text: b, callback_data: b }]);

return [{
  chat_id: $node["Build Context"].json.chat_id,
  text,
  inline_keyboard: { inline_keyboard: rows },
  state_patch: parsed.state_patch || parsed.next_state_patch || {}
}];
